ences"],"constraints":["0 <= first.length,second.length <= 1000","Inputs contain lowercase English letters","Return the lexicographically smallest LCS among ties"],"examples":[{"input":"first = \"abcde\", second = \"ace\"","output":"\"ace\""},{"input":"first = \"abc\", second = \"bac\"","output":"\"ac\""}],"starter_code_by_language":{"JavaScript":"function lexicographicallySmallestLcs(first, second) {\n  // Implement the behavior described in the prompt.\n  return \"\";\n}","Python":"def lexicographically_smallest_lcs(first, second):\n    # Implement the behavior described in the prompt.\n    return \"\"","Java":"public static String lexicographicallySmallestLcs(String first, String second) {\n    // Implement the behavior described in the prompt.\n    return \"\";\n}","C++":"string lexicographicallySmallestLcs(const string& first, const string& second) {\n    // Implement the behavior described in the prompt.\n    return \"\";\n}"},"points":200},{"slug":"weighted-edit-distance","title":"Edit Distance with Operation Costs","problem_statement":"Implement weightedEditDistance(source: String, target: String, insertCost: int, deleteCost: int, replaceCost: int). Return the minimum total cost to transform source into target using character insertion, deletion, and replacement at their respective fixed costs. Matching characters need no operation.","difficulty":"Medium","topic_tags":["Dynamic Programming","Strings","Edit Distance"],"constraints":["0 <= source.length,target.length <= 500","1 <= operation costs <= 1000","Cost fits signed 64-bit"],"examples":[{"input":"source = \"cat\", target = \"cut\", insertCost = 1, deleteCost = 1, replaceCost = 2","output":"2"},{"input":"source = \"abc\", target = \"axc\", insertCost = 4, deleteCost = 5, replaceCost = 6","output":"6"}],"starter_code_by_language":{"JavaScript":"function weightedEditDistance(source, target, insertCost, deleteCost, replaceCost) {\n  // Implement the behavior described in the prompt.\n  return 0;\n}","Python