vior described in the prompt.\n  return 0;\n}","Python":"def longest_common_contiguous_substring(first, second):\n    # Implement the behavior described in the prompt.\n    return 0","Java":"public static int longestCommonContiguousSubstring(String first, String second) {\n    // Implement the behavior described in the prompt.\n    return 0;\n}","C++":"int longestCommonContiguousSubstring(const string& first, const string& second) {\n    // Implement the behavior described in the prompt.\n    return 0;\n}"},"points":150},{"slug":"longest-repeating-subsequence","title":"Longest Repeating Subsequence","problem_statement":"Implement longestRepeatingSubsequence(text: String). Return the maximum length of a subsequence that occurs twice in text using disjoint source positions; the two matched occurrences cannot use the same index.","difficulty":"Medium","topic_tags":["Dynamic Programming","Strings","Subsequences"],"constraints":["0 <= text.length <= 1000","Input contains lowercase English letters"],"examples":[{"input":"text = \"aab\"","output":"1"},{"input":"text = \"axxxy\"","output":"2"}],"starter_code_by_language":{"JavaScript":"function longestRepeatingSubsequence(text) {\n  // Implement the behavior described in the prompt.\n  return 0;\n}","Python":"def longest_repeating_subsequence(text):\n    # Implement the behavior described in the prompt.\n    return 0","Java":"public static int longestRepeatingSubsequence(String text) {\n    // Implement the behavior described in the prompt.\n    return 0;\n}","C++":"int longestRepeatingSubsequence(const string& text) {\n    // Implement the behavior described in the prompt.\n    return 0;\n}"},"points":150},{"slug":"stock-profit-at-most-two-trades","title":"Maximum Profit with Two Stock Trades","problem_statement":"Implement stockProfitAtMostTwoTrades(prices: int[]). Return the maximum profit from at most two transactions. You must sell before buying again; buying and selling on the same day is not allowed.","difficulty":"H