s(int columns) {\n    // Implement the behavior described in the prompt.\n    return 0LL;\n}"},"points":200},{"slug":"regex-match-dot-and-star","title":"Match a Pattern with Dot and Star","problem_statement":"Implement regexMatchDotAndStar(text: String, pattern: String). Return whether the entire text matches a regular-expression pattern where . matches any one character and * matches zero or more repetitions of the immediately preceding atom.","difficulty":"Hard","topic_tags":["Dynamic Programming","Strings","Pattern Matching"],"constraints":["0 <= text.length <= 1000","0 <= pattern.length <= 1000","Pattern uses lowercase letters, . and *","* always follows an atom"],"examples":[{"input":"text = \"aab\", pattern = \"c*a*b\"","output":"true"},{"input":"text = \"mississippi\", pattern = \"mis*is*p.\"","output":"false"}],"starter_code_by_language":{"JavaScript":"function regexMatchDotAndStar(text, pattern) {\n  // Implement the behavior described in the prompt.\n  return false;\n}","Python":"def regex_match_dot_and_star(text, pattern):\n    # Implement the behavior described in the prompt.\n    return False","Java":"public static boolean regexMatchDotAndStar(String text, String pattern) {\n    // Implement the behavior described in the prompt.\n    return false;\n}","C++":"bool regexMatchDotAndStar(const string& text, const string& pattern) {\n    // Implement the behavior described in the prompt.\n    return false;\n}"},"points":200},{"slug":"wildcard-pattern-match","title":"Match a String with Wildcard Tokens","problem_statement":"Implement wildcardPatternMatch(text: String, pattern: String). Return whether the entire text matches pattern, where ? matches exactly one character and * matches any sequence, including empty.","difficulty":"Medium","topic_tags":["Dynamic Programming","Strings","Pattern Matching"],"constraints":["0 <= text.length,pattern.length <= 2000","Text contains lowercase letters","Pattern also contains ? and *"],"examples":[{"input":"text = \"adceb